int evaluatePostfix(char* expr) {
    int stack[100], top = -1;
    for (int i = 0; expr[i] != '\0'; i++) {
        char c = expr[i];
        if (c == ' ') continue;
        if (isdigit(c)) {
            stack[++top] = c - '0';
        } else {
            int b = stack[top--];
            int a = stack[top--];
            int result;
            if (c == '+') result = a + b;
            else if (c == '-') result = a - b;
            else if (c == '*') result = a * b;
            else result = a / b;
            stack[++top] = result;
        }
    }
    return stack[top];
}

