int precedence(char op) {
    if (op == '(') return 3;
    if (op == '*') return 2;
    if (op == '+') return 1;
    return 0;
}

void infixToPostfix(char* expr, char* out) {
    char stack[100]; int top = -1; int oi = 0;
    for (int i = 0; expr[i] != '\0'; i++) {
        char c = expr[i];
        if (isalnum(c)) {
            out[oi++] = c;
        } else if (c == '(') {
            stack[++top] = c;
        } else if (c == ')') {
            while (top >= 0 && stack[top] != '(') {
                out[oi++] = stack[top--];
            }
            top--; // discard the '('
        } else {
            while (top >= 0 && stack[top] != '(' && precedence(stack[top]) >= precedence(c)) {
                out[oi++] = stack[top--];
            }
            stack[++top] = c;
        }
    }
    while (top >= 0) {
        out[oi++] = stack[top--];
    }
    out[oi] = '\0';
}
